create table if not exists time_entries(id text primary key,project_id text not null references projects(id) on delete cascade,user_id text not null references users(id) on delete cascade,description text,started_at text not null,stopped_at text,minutes integer,created_at text not null default current_timestamp);
create table if not exists brand_guidelines(id text primary key,project_id text not null references projects(id) on delete cascade,title text not null,content text not null,sort_order integer not null default 0,created_by text not null references users(id),created_at text not null default current_timestamp,updated_at text not null default current_timestamp);
create table if not exists studio_branding(id integer primary key check(id=1),studio_name text not null default 'The Fourth Wall',logo_file_id text references project_files(id) on delete set null,accent_color text not null default '#B89246',email_footer text,updated_at text not null default current_timestamp);
create table if not exists user_settings(user_id text primary key references users(id) on delete cascade,language text not null default 'en',biometric_lock integer not null default 0 check(biometric_lock in(0,1)),theme text not null default 'light' check(theme in('light','dark')),updated_at text not null default current_timestamp);
create table if not exists testimonials(id text primary key,project_id text not null references projects(id) on delete cascade,user_id text not null references users(id),rating integer check(rating between 1 and 5),quote text,referral_name text,referral_email text,created_at text not null default current_timestamp);
create index if not exists time_entries_project_idx on time_entries(project_id,started_at desc);
create index if not exists guidelines_project_idx on brand_guidelines(project_id,sort_order);
create index if not exists testimonials_project_idx on testimonials(project_id,created_at desc);
